#include <algorithm>
#include <condition_variable>
#include <cstdint>
#include <deque>
#include <format>
#include <iostream>
#include <mutex>
#include <optional>
#include <stop_token>
#include <thread>

// The one place the producer and the worker meet. The full policy is part of the type, so nobody
// can hand an item over without having decided what happens when there is no room, and what is
// lost is counted rather than guessed at.
class Handover {
 public:
  explicit Handover(std::ptrdiff_t capacity) : capacity_(capacity) {}

  void push(std::int64_t item) {
    {
      const std::lock_guard guard(mutex_);
      if (std::ssize(items_) == capacity_) {
        dropped_sum_ += items_.front();
        ++dropped_;
        items_.pop_front();
      }
      items_.push_back(item);
      high_water_ = std::max(high_water_, std::ssize(items_));
    }
    ready_.notify_one();
  }

  // Waits for an item or for the stop request. Waiting with the token is what lets shutdown work
  // without a second signal and without a poison value in the queue.
  [[nodiscard]] std::optional<std::int64_t> pop(std::stop_token stop) {
    std::unique_lock lock(mutex_);
    if (!ready_.wait(lock, stop, [this] { return !items_.empty(); })) return std::nullopt;
    const std::int64_t item = items_.front();
    items_.pop_front();
    return item;
  }

  [[nodiscard]] bool empty() const {
    const std::lock_guard guard(mutex_);
    return items_.empty();
  }

  [[nodiscard]] std::int64_t dropped() const {
    const std::lock_guard guard(mutex_);
    return dropped_;
  }

  [[nodiscard]] std::int64_t dropped_sum() const {
    const std::lock_guard guard(mutex_);
    return dropped_sum_;
  }

  [[nodiscard]] std::ptrdiff_t high_water() const {
    const std::lock_guard guard(mutex_);
    return high_water_;
  }

 private:
  mutable std::mutex mutex_;
  std::condition_variable_any ready_;
  std::ptrdiff_t capacity_;
  std::deque<std::int64_t> items_;
  std::int64_t dropped_ = 0;
  std::int64_t dropped_sum_ = 0;
  std::ptrdiff_t high_water_ = 0;
};

int main() {
  constexpr std::ptrdiff_t capacity = 8;
  constexpr std::int64_t produced = 1000;

  Handover queue(capacity);
  std::int64_t done = 0;
  std::int64_t done_sum = 0;
  {
    // The worker owns `done` and `done_sum` for as long as it runs, and the join at the end of
    // this scope is what makes them safe to read afterwards.
    const std::jthread worker([&queue, &done, &done_sum](std::stop_token stop) {
      while (const std::optional<std::int64_t> item = queue.pop(stop)) {
        ++done;
        done_sum += *item;
      }
    });

    for (std::int64_t item = 1; item <= produced; ++item) queue.push(item);
    while (!queue.empty()) std::this_thread::yield();  // let the worker finish what survived
  }  // the jthread destructor requests the stop and joins

  const std::int64_t expected_sum = produced * (produced + 1) / 2;
  std::cout << std::format("capacity {}, produced {}\n", capacity, produced);
  std::cout << std::format("done + dropped = {}\n", done + queue.dropped());
  std::cout << std::format("sum of done and dropped = {}, expected {}\n", done_sum + queue.dropped_sum(),
                           expected_sum);
  std::cout << std::format("the queue never held more than {} items: {}\n", capacity,
                           queue.high_water() <= capacity ? "yes" : "no");
}

enum class WhenFull { DropOldest, DropNewest, Block };

class RecordQueue {
 public:
  RecordQueue(std::ptrdiff_t capacity, WhenFull policy);
  void push(std::vector<std::byte> record);                     // never blocks under DropOldest
  [[nodiscard]] std::optional<std::vector<std::byte>> pop(std::stop_token stop);
  void stop_accepting();                                        // step 1 of the shutdown
  [[nodiscard]] std::ptrdiff_t depth() const;
  [[nodiscard]] std::ptrdiff_t high_water() const;
  [[nodiscard]] std::int64_t dropped() const;
};
